CREATE TABLE IF NOT EXISTS learn_courses(id BIGSERIAL PRIMARY KEY,course_key VARCHAR(190) NOT NULL UNIQUE,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',locale VARCHAR(10) NOT NULL DEFAULT 'fa',status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_chapters(id BIGSERIAL PRIMARY KEY,course_id BIGINT NOT NULL REFERENCES learn_courses(id) ON DELETE CASCADE,title TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_lessons(id BIGSERIAL PRIMARY KEY,chapter_id BIGINT NOT NULL REFERENCES learn_chapters(id) ON DELETE CASCADE,lesson_key VARCHAR(190) NOT NULL UNIQUE,title TEXT NOT NULL,body TEXT NOT NULL DEFAULT '',block_document TEXT NOT NULL DEFAULT '',block_schema_version INTEGER NOT NULL DEFAULT 1,position INTEGER NOT NULL DEFAULT 0,status VARCHAR(20) NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','archived')),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_instructors(id BIGSERIAL PRIMARY KEY,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,display_name TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS learn_students(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS learn_enrollments(id BIGSERIAL PRIMARY KEY,student_id BIGINT NOT NULL REFERENCES learn_students(id) ON DELETE CASCADE,course_id BIGINT NOT NULL REFERENCES learn_courses(id) ON DELETE CASCADE,status VARCHAR(20) NOT NULL DEFAULT 'active' CHECK(status IN('active','completed','cancelled')),enrolled_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(student_id,course_id));
CREATE TABLE IF NOT EXISTS learn_progress(enrollment_id BIGINT NOT NULL REFERENCES learn_enrollments(id) ON DELETE CASCADE,lesson_id BIGINT NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,completed BOOLEAN NOT NULL DEFAULT FALSE,progress_percent INTEGER NOT NULL DEFAULT 0 CHECK(progress_percent BETWEEN 0 AND 100),updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(enrollment_id,lesson_id));
CREATE TABLE IF NOT EXISTS learn_quizzes(id BIGSERIAL PRIMARY KEY,lesson_id BIGINT NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,title TEXT NOT NULL,config_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS learn_assignments(id BIGSERIAL PRIMARY KEY,lesson_id BIGINT NOT NULL REFERENCES learn_lessons(id) ON DELETE CASCADE,title TEXT NOT NULL,instructions TEXT NOT NULL DEFAULT '',due_days INTEGER);
CREATE TABLE IF NOT EXISTS learn_certificates(id BIGSERIAL PRIMARY KEY,enrollment_id BIGINT NOT NULL UNIQUE REFERENCES learn_enrollments(id) ON DELETE CASCADE,certificate_code VARCHAR(190) NOT NULL UNIQUE,issued_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO schema_migrations(version) VALUES('10.16.0') ON CONFLICT(version) DO NOTHING;